class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("A roll cannot score negative or more than 10 points")

        frames = self._frames()
        if len(frames) == 10:
            if self._tenth_frame_complete(frames[9]):
                raise ValueError("Cannot roll after the game already has ten frames")
            current = frames[9]
            tenth = True
        else:
            current = frames[-1] if frames else []
            tenth = False

        if len(current) == 1 and not tenth and current[0] + pins > 10:
            raise ValueError("Two rolls in a frame cannot score more than 10 points")
        if len(current) == 2 and current[1] != 10 and current[1] + pins > 10:
            raise ValueError(
                "The second bonus roll after a strike cannot exceed 10 "
                "points if the first bonus roll is not a strike"
            )

        self.rolls.append(pins)

    def score(self):
        frames = self._frames()
        if len(frames) != 10 or not self._tenth_frame_complete(frames[9]):
            raise ValueError("Cannot score an incomplete game")

        total = 0
        for index, frame in enumerate(frames):
            if index < 9:
                if len(frame) == 1:  # strike
                    total += 10 + self.rolls[index + 1] + self.rolls[index + 2]
                elif frame[0] + frame[1] == 10:  # spare
                    total += 10 + self.rolls[index + 2]
                else:  # open frame
                    total += frame[0] + frame[1]
            else:  # tenth frame: just sum the pins knocked down
                total += sum(frame)
        return total

    def _frames(self):
        """Group the rolls into frames. The last frame may be incomplete."""
        frames = []
        i = 0
        for frame_no in range(10):
            if i >= len(self.rolls):
                break
            if frame_no < 9:
                if self.rolls[i] == 10:
                    frames.append([self.rolls[i]])
                    i += 1
                elif i + 1 < len(self.rolls):
                    frames.append([self.rolls[i], self.rolls[i + 1]])
                    i += 2
                else:
                    frames.append([self.rolls[i]])
                    i += 1
            else:
                frames.append(self.rolls[i:])
        return frames

    @staticmethod
    def _tenth_frame_complete(rolls):
        if len(rolls) >= 3:
            return rolls[0] == 10 or rolls[0] + rolls[1] == 10
        if len(rolls) == 2:
            return rolls[0] + rolls[1] < 10
        return False

